package org.jsoup.helper;

import java.net.IDN;
import java.net.MalformedURLException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URLDecoder;
import java.net.URLEncoder;
import static org.jsoup.helper.DataUtil.UTF_8;

public class UrlBuilderTest {

    @Mock
    private Connection.KeyVal keyValMock;

    public String buildUrl() throws UnsupportedEncodingException {
        Map<String, String> keyVals = new HashMap<>();
        keyVals.put("c", "3");
        urlBuilderMock.appendKeyVal(keyVals);
        return getExpectedString(keyVals);
    }

    @Test
    public void testBuild_URL_NonEmptyMap() throws UnsupportedEncodingException {
        URL inputUrl = new URI("http://example.com/path?a=1&b=2");
        Map<String, String> keyVals = new HashMap<>();
        keyVals.put("c", "3");
        urlBuilderMock.appendKeyVal(keyVals);
    }

    @Test
    public void testBuild_URL_NonStringValue() throws UnsupportedEncodingException {
        URL inputUrl = new URI("http://example.com/path?a=1&b=2");
        Map<String, String> keyVals = new HashMap<>();
        keyVals.put("c", "3");
        urlBuilderMock.appendKeyVal(keyVals);
    }

    @Test
    public void testBuild_URL_NullMap() throws UnsupportedEncodingException {
        URL inputUrl = new URI("http://example.com/path?a=1&b=2");
        Map<String, String> keyVals = null;
        urlBuilderMock.appendKeyVal(keyVals);
    }

    private String getExpectedString(Map<String, String> keyVals) throws URISyntaxException {
        return "http://" + inputUrl.getScheme() + "//" + inputUrl.getHost() + "/" + URLDecoder.decode(inputUrl.getPath(), "UTF-8") + "?key=c&value=3";
    }
}
